// Local prototype only: no mailbox, uploads, permission changes or external mutations.
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let screen='new',accepted=false,updated=false,amountApplied=false,fileApplied=false,priorAmount=null,amountOK=false,dateOK=false,toastTimer;
let data={client:'บริษัท รุ่งเรือง เทรดดิ้ง',contact:'คุณอร · ฝ่ายบัญชี',title:'พิจารณาเรียกชำระค่าสินค้า',amount:'450000',date:'2026-09-15',summary:'ลูกค้าขอให้พิจารณาแนวทางติดตามยอดค้าง พร้อมแจ้งเอกสารที่ต้องเตรียมเพิ่ม',owner:'นภา วัฒนกิจ',type:'ข้อพิพาททางสัญญา'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function panel(title,body,tag=''){return `<section class="panel"><div class="panelhead"><h3>${title}</h3>${tag}</div><div class="panelbody">${body}</div></section>`}
function field(key,label,badge,extra=''){return `<div class="form-row"><div class="field-top"><label for="${key}">${label}</label><span class="tag ${badge==='ต้องยืนยัน'?'amber':''}">${badge}</span></div><input id="${key}" data-field="${key}" value="${esc(data[key])}" ${key==='amount'?'type="number" min="0"':key==='date'?'type="date"':'type="text"'}>${extra}</div>`}
function sourceMail(reply=false){return `<div class="inbox-source">${panel(reply?'บทสนทนาเดิม · มีเมลใหม่':'เมลต้นทาง',`<h3>Re: ขอปรึกษาเรื่องลูกค้าค้างชำระ</h3><div class="mailmeta"><span class="avatar">อ</span><div><b>คุณอร · รุ่งเรือง เทรดดิ้ง</b><small style="display:block">${reply?'วันนี้ 14:20':'วันนี้ 09:12'} · ถึงทีมกฎหมาย · ข้อมูลสมมติ</small></div></div>${reply?`<div class="timeline-mail"><small>09:12 · ลูกค้าส่งเรื่องครั้งแรก</small><p>ยอดค้าง 450,000 บาท แนบสัญญา ใบแจ้งหนี้ และเมลติดตาม</p></div><div class="timeline-mail"><span class="tag">Reply ใหม่</span><p>ขอส่งใบส่งมอบที่ลงนามรับเพิ่มเติมค่ะ และแจ้งว่าลูกค้าได้โอนมาแล้ว <span class="mail-highlight">50,000 บาท</span> คงเหลือยอดค้าง <span class="mail-highlight">400,000 บาท</span> แนบสัญญาเดิมมาให้อีกครั้งด้วยค่ะ</p></div>`:`<div class="mailbody">เรียนทีมทนาย<br>บริษัทคู่ค้ายังค้างชำระค่าสินค้า <span class="mail-highlight">450,000 บาท</span> รบกวนช่วยพิจารณาว่าควรดำเนินการอย่างไรค่ะ<br><br>หากเป็นไปได้ อยากได้รับคำแนะนำภายใน <span class="mail-highlight">15 กันยายน 2569</span><br><br>แนบเอกสารที่มีมาให้ตรวจสอบค่ะ</div>`}<div class="files">${(reply?['ใบส่งมอบลงนาม.pdf','สัญญาซื้อขาย.pdf']:['สัญญาซื้อขาย.pdf','ใบแจ้งหนี้.pdf','อีเมลติดตาม.eml']).map((f,i)=>`<button class="file" data-doc="${f}"><span>${f.endsWith('eml')?'EML':'PDF'}</span>${f}<small>${reply&&i===1?'ไฟล์ซ้ำ · ไม่เพิ่มสำเนา':'ดูต้นทาง'}</small></button>`).join('')}</div>`)}<p class="caption">ข้อความที่เน้นคือแหล่งของข้อมูลที่เสนอกรอก ไม่ใช่ข้อเท็จจริงที่สำนักงานยืนยันแล้ว</p></div>`}
function newForm(){return `<div class="mini-steps"><b>01 รับเมลและเตรียมข้อมูล ✓</b><span>→</span><b>02 ทนายตรวจและรับงาน</b><span>→</span><span>03 เริ่มพิจารณาเรื่อง</span></div><div class="countband"><span>✓ เตรียมข้อมูลจากเมลและไฟล์แนบ</span><span>✓ เสนอจับคู่ลูกค้าเดิม</span><span>ตรวจยืนยัน 2 จุดสำคัญ</span></div><div class="intake-grid">${sourceMail()}<div>${panel('ข้อมูลพร้อมรับงาน',`${field('title','ชื่อเรื่อง','ระบบเสนอ')}${field('client','ลูกค้า','เสนอจับคู่ลูกค้าเดิม','<div class="field-help">ชื่อตรงกับทะเบียนตัวอย่าง · ตรวจชื่อก่อนรับงาน</div>')}${field('contact','ผู้ติดต่อ','พบจากต้นทาง')}${field('amount','ยอดที่ลูกค้าแจ้ง (บาท)','ต้องยืนยัน',`<button class="source-link" data-source="amount">ดูข้อความต้นทาง ↗</button><div class="inline-confirm"><input id="amountOK" type="checkbox" ${amountOK?'checked':''}><label for="amountOK">ตรวจยอดจากเมลแล้ว · ยังต้องตรวจหลักฐานประกอบ</label></div>`)}${field('date','วันที่ลูกค้าขอรับคำตอบ','ต้องยืนยัน',`<div class="field-help">ไม่ใช่กำหนดทางกฎหมาย และยังไม่ใช่วันที่สำนักงานตกลงส่งงาน</div><div class="inline-confirm"><input id="dateOK" type="checkbox" ${dateOK?'checked':''}><label for="dateOK">ยืนยันว่าเป็นวันที่ลูกค้าร้องขอ</label></div>`)}<div class="form-row"><div class="field-top"><label for="summary">สิ่งที่ลูกค้าต้องการ</label><span class="tag">ระบบสรุป · แก้ได้</span></div><textarea id="summary" data-field="summary">${esc(data.summary)}</textarea></div><div class="form-row"><label for="owner">ผู้รับผิดชอบเรื่อง</label><select id="owner" data-field="owner">${['นภา วัฒนกิจ','ธนา ศิริกุล','มินตรา พงษ์ชัย','ปกรณ์ สุขใจ'].map(n=>`<option ${data.owner===n?'selected':''}>${n}</option>`).join('')}</select><p class="field-help">รับผิดชอบเรื่องก่อน · เลือกผู้ตรวจและผู้แก้เอกสารได้ภายหลัง</p></div><div class="notice sectiongap"><b>ข้อมูลที่ยังขาด</b><br>หลักฐานส่งมอบที่ลงนามรับ และประวัติการชำระเงิน<br>ขอเพิ่มภายหลังได้ ไม่ต้องกรอกให้ครบก่อนรับเรื่อง</div>`,'<span class="tag amber">รอคนยืนยัน</span>')}</div></div><div class="intake-actions"><div><b id="remaining">${[amountOK,dateOK].filter(Boolean).length}/2 จุดสำคัญที่ตรวจแล้ว</b><small>รับผิดชอบเรื่อง ≠ ตกลงรับฟ้อง · ยังไม่ส่งข้อความลูกค้า</small></div><div class="row"><button data-action="later">เก็บไว้ตรวจภายหลัง</button><button class="primary" data-action="accept">ยืนยันข้อมูลและรับงาน →</button></div></div><p class="error" id="formError" role="alert"></p>`}
function updateForm(){return `<div class="countband"><span>↳ Reply อยู่ในเรื่อง IN-2026-014</span><span>เอกสารใหม่ 1 ไฟล์ · ซ้ำ 1 ไฟล์</span><span>ข้อมูลเปลี่ยน 1 จุด</span></div><div class="intake-grid">${sourceMail(true)}<div>${panel('ตรวจเฉพาะสิ่งที่เพิ่มจากรอบก่อน',`<div class="match"><b>เรื่องเดิม: ${esc(data.title)}</b><br>${esc(data.client)} · ${esc(data.owner)}<br>อ้างอิงบทสนทนาเดิม · ไม่สร้างเรื่องใหม่</div><div class="form-row"><h3>ยอดค้างที่ลูกค้าแจ้งเปลี่ยนไป</h3><div class="diff"><div><small>ข้อมูลที่ยืนยันไว้</small><b>${Number(priorAmount??data.amount).toLocaleString()} บาท</b></div><span>→</span><div class="new-value"><small>ข้อมูลใหม่จาก Reply</small><b>400,000 บาท</b></div></div><p class="field-help">ลูกค้าแจ้งว่าชำระเพิ่ม 50,000 บาท ต้องตรวจหลักฐานก่อนใช้คำนวณต่อ</p><div class="inline-confirm"><input id="applyAmount" type="checkbox" ${updated?'disabled':''} ${amountApplied?'checked':''}><label for="applyAmount">อัปเดตยอดตามข้อมูลใหม่ที่ตรวจแล้ว</label></div></div><div class="form-row"><h3>เอกสารที่ส่งเพิ่ม</h3><div class="statusline">＋ ใบส่งมอบลงนาม.pdf <span class="tag green">ใหม่</span></div><div class="statusline">＝ สัญญาซื้อขาย.pdf <span class="tag">ซ้ำ</span></div><div class="inline-confirm"><input id="applyFile" type="checkbox" ${(!updated||fileApplied)?'checked':''} ${updated?'disabled':''}><label for="applyFile">เพิ่มไฟล์ใหม่เข้าเรื่องเดิม</label></div></div><div class="notice sectiongap"><b>ผลกระทบที่ต้องทบทวน</b><br>ร่างหรือความเห็นเดิมอาจใช้ยอด 450,000 บาท ระบบทำเครื่องหมายให้ทบทวน แต่ไม่แก้ Word หรือยืนยันฉบับใหม่เอง</div><p class="caption">เก็บค่าเดิม เมลต้นทาง ผู้ยืนยัน และเวลาที่อัปเดตไว้ในประวัติ</p>`,updated?'<span class="tag green">ตรวจ Reply นี้แล้ว</span>':'<span class="tag amber">รอตรวจข้อมูลใหม่</span>')}<div class="intake-actions"><div><b>${updated?'อัปเดตเรื่องเดิมแล้ว':'เลือกเฉพาะข้อมูลที่ต้องการใช้'}</b><small>ไม่เขียนทับข้อมูลเดิมอัตโนมัติ</small></div><button class="primary" data-action="apply" ${updated?'disabled':''}>ยืนยันรายการที่เลือก</button></div></div></div>`}
function acceptedPane(){if(!accepted)return `<div class="intake-success"><h2>ยังไม่มีเรื่องที่คุณรับในรอบตัวอย่างนี้</h2><p class="muted">เริ่มจากตรวจข้อมูลที่เตรียมจากเมล แล้วกดรับผิดชอบเรื่อง</p><button class="primary sectiongap" data-screen="new">ไปหน้ารับงาน →</button></div>`;return `<div class="intake-success"><span class="tag green">✓ รับผิดชอบเรื่องแล้ว</span><h2>${esc(data.title)}</h2><p class="muted">IN-2026-014 · ${esc(data.client)} · ${esc(data.owner)}</p><div class="success-grid">${panel('ข้อมูลที่บันทึก',`<dl class="facts"><div><dt>ยอดที่ลูกค้าแจ้ง</dt><dd>${Number(data.amount).toLocaleString()} บาท</dd></div><div><dt>วันที่ขอคำตอบ</dt><dd>${esc(data.date)}</dd></div><div><dt>สถานะ</dt><dd>รอประเมิน</dd></div></dl>`)}${panel('พร้อมให้ทำงานต่อ',`<p>เมลต้นทางและไฟล์แนบอยู่ในเรื่องเดียวกัน พร้อมสรุปประเด็นและรายการข้อมูลที่ยังขาด</p><p class="caption">${updated?'มี Reply ใหม่ที่ตรวจแล้ว · ร่างเดิมรอทบทวน':'ผู้ตรวจและผู้แก้จะเลือกเมื่อเตรียมเอกสาร'}</p>`)}</div><div class="row sectiongap"><button class="primary" data-action="start-assess">เริ่มพิจารณาเรื่อง</button><button data-screen="update">ลองเมล Reply ที่ส่งเพิ่ม →</button></div><p class="caption">สถานะจำลองในหน้านี้ ไม่สร้างข้อมูลในแอปจริง</p></div>`}
function render(){document.querySelectorAll('[data-screen]').forEach(e=>e.classList.toggle('selected',e.dataset.screen===screen));$('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">EMAIL INTAKE / LAWYER WORKSPACE</div><h1>${screen==='new'?'เมลเข้ามา ข้อมูลพร้อมรับงาน':screen==='update'?'ลูกค้า Reply มา มีอะไรเปลี่ยนบ้าง':'รับเรื่องแล้ว เริ่มงานต่อได้เลย'}</h1><p>${screen==='new'?'ตรวจข้อมูลที่เตรียมให้ แก้เฉพาะจุดที่ต้องการ แล้วรับงานในครั้งเดียว':screen==='update'?'อ่านเฉพาะข้อมูลใหม่ เทียบกับสิ่งที่ยืนยันไว้ในเรื่องเดิม':'ข้อมูล เอกสาร และคนรับผิดชอบอยู่ด้วยกัน'}</p></div><span class="tag">ข้อมูลสมมติ</span></div>${screen==='new'?newForm():screen==='update'?updateForm():acceptedPane()}`}
function modal(title,body){$('#modalContent').innerHTML=`<div class="modalhead"><h3>${title}</h3><button data-action="close" aria-label="ปิด">✕</button></div><div class="modalbody">${body}</div>`;$('#modal').showModal()}
document.addEventListener('input',e=>{if(e.target.dataset.field){data[e.target.dataset.field]=e.target.value;if(e.target.dataset.field==='amount'){amountOK=false;$('#amountOK').checked=false}if(e.target.dataset.field==='date'){dateOK=false;$('#dateOK').checked=false}if($('#remaining'))$('#remaining').textContent=[amountOK,dateOK].filter(Boolean).length+'/2 จุดสำคัญที่ตรวจแล้ว'}});
document.addEventListener('change',e=>{if(e.target.id==='amountOK')amountOK=e.target.checked;if(e.target.id==='dateOK')dateOK=e.target.checked;if(e.target.dataset.field)data[e.target.dataset.field]=e.target.value;if($('#remaining'))$('#remaining').textContent=[amountOK,dateOK].filter(Boolean).length+'/2 จุดสำคัญที่ตรวจแล้ว'});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.screen){screen=b.dataset.screen;render();return}if(b.dataset.doc){modal(b.dataset.doc,'<span class="tag">ไฟล์ตัวอย่าง</span><p class="sectiongap">ระบบจริงจะแสดงต้นฉบับตรงนี้ พร้อมตำแหน่งที่ดึงข้อมูลมาใช้ เพื่อให้ตรวจได้โดยไม่ออกจากหน้ารับงาน</p>');return}if(b.dataset.source){modal('ข้อความต้นทาง','<div class="mailbody">บริษัทคู่ค้ายังค้างชำระค่าสินค้า <mark>450,000 บาท</mark></div><p>ยอดตามที่ลูกค้าแจ้ง ยังต้องตรวจหลักฐานและประวัติชำระเงิน</p>');return}let a=b.dataset.action;if(a==='reset'){location.reload();return}if(a==='close'){$('#modal').close();return}if(a==='later'){toast('เก็บข้อมูลที่กรอกไว้ในรอบตัวอย่างนี้แล้ว · ยังไม่รับงาน');return}if(a==='accept'){if(!data.title.trim()||!data.client.trim()||!data.amount||Number(data.amount)<0||!data.date||!amountOK||!dateOK){$('#formError').textContent='ตรวจชื่อเรื่อง ลูกค้า ยอด วันที่ และยืนยัน 2 จุดสำคัญก่อนรับงาน';toast('ยังมีข้อมูลสำคัญที่ต้องตรวจ');return}accepted=true;screen='accepted';render();return}if(a==='apply'){if(!$('#applyAmount').checked&&!$('#applyFile').checked){toast('เลือกรายการที่ต้องการอัปเดตก่อน');return}priorAmount=data.amount;amountApplied=$('#applyAmount').checked;fileApplied=$('#applyFile').checked;if(amountApplied)data.amount='400000';updated=true;render();toast('อัปเดตเฉพาะรายการที่เลือกแล้ว · เก็บประวัติค่าเดิม');return}if(a==='start-assess'){modal('พร้อมเริ่มพิจารณาเรื่อง',`<h3>${esc(data.title)}</h3><p class="sectiongap">${esc(data.summary)}</p><div class="notice sectiongap">ตรวจสัญญาและหลักฐานประกอบก่อนยืนยันแนวทาง ข้อมูลที่ยังขาดให้ขอเพิ่มในอีเมลชุดเดิม</div><p>ขั้นต่อไป: สรุปข้อเท็จจริง → เลือกแนวทาง → เตรียม Word → เลือกผู้ตรวจ</p><a href="index.html">ดูต้นแบบขั้นประเมินและตรวจเอกสาร →</a><p class="caption">ลิงก์เปิดตัวอย่างอีกชุด ยังไม่ส่งข้อมูลข้ามต้นแบบ</p>`);return}});render();
